import { Hono } from "hono";
import { registerJobsRoutes } from "./jobs";
import {
  registerUploadRoutes,
  sweepExpiredJobs,
  sweepExpiredRelayObjects,
  sweepExpiredUploads,
} from "./uploads";
import { getRelay, postRelay } from "./relay";
import { postDevice, resolveDevice, timingSafeEqual } from "./devices";

// Env is generated by `npm run types` (wrangler types) once deployed keys exist.
// Optional bindings stay optional so `vitest` runs without Cloudflare.
export interface Env {
  MEDIA: R2Bucket;
  PIPELINE?: Workflow;
  AI?: Ai;
  RL?: RateLimit;
  SCOUT_ORDER: string;
  GROUND_ORDER: string;
  AI_GATEWAY_ID: string;
  WORKERS_AI_MODELS?: string;
  SCOUT_MODEL_TIMEOUT_MS?: string;
  ENV?: string;
  META_API_KEY?: string;
  /** Retired as the bearer (R10-01): the per-install device key is now the
   * credential. Kept deployed only as a public client identifier during the
   * migration window — auth no longer compares against it. */
  ECHO_APP_TOKEN?: string;
  /** W11-06: `legacy` keeps the W3-05 per-candidate video-first ground step;
   * any other value (or unset) runs the SAM lens (ladder + cache +
   * governor). Removed or recorded in W11-10. */
  GROUND_MODE?: string;
  /** W11-06: reserved for the W11-07 multi-phrase probe outcome (default
   * off; probe TBD in docs/measurements.md, so single-phrase-per-call). */
  MULTI_PHRASE?: string;
  /** R10-05 (review 0010, F4): daily SAM-frame cap the create paths
   * reserve against (spend.ts). Unset → 1200, five jobs at the 240
   * ceiling. Ops: docs/operations/spend.md. */
  DAILY_MAX_SAM_FRAMES?: string;
  /** R10-05: exactly `on` rejects every job create with 503
   * spend_disabled without touching the ledger. */
  SPEND_KILL_SWITCH?: string;
}

// Kept module-private: workerd treats every named export as a potential
// entrypoint, and a plain string const breaks local dev (W3-03 live verify).
const VERSION = "0.1.0";

// `timingSafeEqual` now lives in `devices.ts` (it compares the stored device
// key); re-exported so the S-reviewed surface stays importable from here.
export { timingSafeEqual };

interface HeaderReader {
  header(name: string): string | undefined;
}

function bearerToken(req: HeaderReader): string | null {
  const header = req.header("Authorization") ?? req.header("authorization");
  if (!header) return null;
  const prefix = "Bearer ";
  if (!header.startsWith(prefix)) return null;
  const token = header.slice(prefix.length).trim();
  return token === "" ? null : token;
}

function clientIp(req: HeaderReader): string {
  const direct = req.header("CF-Connecting-IP")?.trim();
  if (direct) return direct;
  const forwarded = req.header("X-Forwarded-For")?.split(",")[0]?.trim();
  if (forwarded) return forwarded;
  return "unknown";
}

// The context carries the authenticated device id (R10-01): the middleware
// resolves the bearer to a per-install id, and handlers read it to enforce
// ownership of the jobs, uploads, and relay objects that id created.
export type AppEnv = { Bindings: Env; Variables: { deviceId: string } };

export const app = new Hono<AppEnv>();

// Auth + rate limit for every /v1/* route except the public health probe and
// the device-mint route. Registered before any route so later slices inherit
// the policy automatically. Future routes only add handlers.
//
// F1 (R10-01): the bearer is now a per-install device key, resolved against R2
// — one install cannot read or delete another's. Two limits: an IP-based one
// in front of auth (unauthenticated traffic and device minting are throttled
// too, not just holders of the old shared token) and a per-install one behind
// it.
app.use("/v1/*", async (c, next) => {
  const ip = clientIp(c.req);
  const rl = c.env?.RL;

  // In front of auth: the shared-secret gate only throttled token holders and
  // left unauthenticated requests unlimited. Key on IP alone so the limit
  // exists before any credential is checked.
  if (rl) {
    const { success } = await rl.limit({ key: `pre:${ip}` });
    if (!success) return c.json({ ok: false, error: "rate_limited" }, 429);
  }

  // Health is public; device minting is public but IP-throttled above.
  if (c.req.path === "/v1/health" || c.req.path === "/v1/device") {
    return next();
  }

  const got = bearerToken(c.req);
  if (!got) return c.json({ ok: false, error: "unauthorized" }, 401);
  const deviceId = await resolveDevice(c.env, got);
  if (deviceId === null) {
    return c.json({ ok: false, error: "unauthorized" }, 401);
  }
  c.set("deviceId", deviceId);

  // Behind auth: throttle a single install, re-keying the old `token:ip`
  // limit onto the device id.
  if (rl) {
    const { success } = await rl.limit({ key: `dev:${deviceId}:${ip}` });
    if (!success) return c.json({ ok: false, error: "rate_limited" }, 429);
  }

  return next();
});

// Public liveness probe. No auth, no rate limit: load balancers and the
// deploy check in W0-05 must reach it without credentials.
app.get("/v1/health", (c) => {
  return c.json({
    ok: true,
    version: VERSION,
    metaKeyConfigured: Boolean(c.env?.META_API_KEY),
    // W3-04: which scout providers can run (workersAi needs the AI binding).
    providers: {
      workersAi: Boolean(c.env?.AI),
      metaKey: Boolean(c.env?.META_API_KEY),
    },
  });
});

// Frozen in W3-03: jobs lifecycle (create → poll → result → delete).
registerJobsRoutes(app);

// W11-05: resumable v1.1 uploads (auth + rate limit above apply).
registerUploadRoutes(app);

// R10-01: first-run mint of the per-install device key. Public but throttled
// by the pre-auth IP limit in the gate above.
app.post("/v1/device", postDevice);

// Zero-knowledge relay (W4-05): ciphertext in, ciphertext out, 30 min TTL.
// Auth + rate limit above apply; the bundle key never reaches this worker.
app.post("/v1/relay", postRelay);
app.get("/v1/relay/:code", getRelay);

app.notFound((c) => c.json({ ok: false, error: "not_found" }, 404));

// The Workflow class must be exported from the worker entry or the
// `echo-pipeline` binding in wrangler.jsonc cannot resolve on deploy.
export { EchoPipeline } from "./pipeline";

export default {
  fetch: app.fetch,
  // Hourly cron (wrangler.jsonc `triggers.crons`): staged uploads and
  // orphaned idempotency records otherwise expire only when someone next
  // touches the upload API; R10-02 adds the 24 h retention sweep for
  // terminal jobs and the no-GET expiry of abandoned relay codes. The R2
  // lifecycle rule in wrangler.jsonc is the backstop for whatever a cycle
  // misses.
  async scheduled(_controller: ScheduledController, env: Env): Promise<void> {
    await sweepExpiredUploads(env);
    await sweepExpiredJobs(env);
    await sweepExpiredRelayObjects(env);
  },
};
